message.content:
{
  "description": "The creature is shown in right-facing side profile as a single quadrupedal chimera with a pale pink, smooth-skinned axolotl-like head, underbody, and limbs combined with a dense dorsal armor of overlapping dark brown-gray pangolin-like scales. It has a broad flat head with large dark eyes and six pink feathery external gills projecting from the neck behind the head, four stout wrinkled legs with clawed feet supporting the body, and a long thick tapering tail that is scaled dorsally and pale and ridged ventrally, the scales covering the entire back from the neck to the tail tip while the belly, throat, legs and underside of the tail remain exposed pale skin.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flattened and rounded axolotl-like head with smooth pale pink to off-white skin, large round dark eyes with a light blue-gray iris and glossy highlight, small circular pink nostrils near the snout tip, and a wide mouth with a slightly upturned lower jaw",
      "where": "at the anterior end of the body, facing to the right"
    },
    {
      "part": "gills",
      "looks_like": "six fleshy pink stalk-like external gills bearing dense fine feathery red-pink filaments along their length, three large prominent stalks curving outward and backward on the near side of the neck and three smaller stalks visible on the far side above and behind the head",
      "where": "arising from the sides of the neck immediately behind the head"
    },
    {
      "part": "legs",
      "looks_like": "four thick, stout, columnar limbs with wrinkled pale pink fleshy skin, visible joints and folds, tapering slightly toward the feet",
      "where": "ventrally under the body, two forelimbs under the chest and two hindlimbs under the mid-body and rear"
    },
    {
      "part": "feet",
      "looks_like": "pale pink feet with five short splayed digits each tipped with a small dark curved claw, with wrinkled skin on the toes and sole",
      "where": "at the distal end of each leg, flat on the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick, tapering tail with overlapping scales on its dorsal and lateral surfaces and exposed pale pink ridged wrinkled skin on its ventral surface, narrowing toward the tip that extends beyond the left edge of the image",
      "where": "projecting posteriorly from the rear of the body to the left"
    },
    {
      "part": "scales",
      "looks_like": "dense overlapping rounded keratinous scales colored dark brown-gray in the center fading to tan at the edges with fine concentric ridging, arranged in diagonal rows",
      "where": "covering the entire dorsal surface from the base of the gills along the back and over the dorsal and lateral sides of the tail"
    },
    {
      "part": "plates",
      "looks_like": "the same overlapping scale-plates forming a continuous dorsal armor, each plate is a broad curved armor plate with a smooth surface and lighter margin",
      "where": "forming the dorsal armor over the back and tail, same as the scales"
    },
    {
      "part": "markings",
      "looks_like": "small irregular dark gray to black speckles and mottling",
      "where": "scattered on the dorsal and lateral surfaces of the head, especially around the eyes, cheeks and crown behind the gills"
    }
  ],
  "attached_objects": [],
  "animals": [
    "axolotl",
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
